[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(Mandatory=$true)][string]$PacketPath)
$ErrorActionPreference='Stop';$root=(Resolve-Path -LiteralPath $ProjectRoot).Path;if([IO.Path]::IsPathRooted($PacketPath)){throw 'PacketPath must be project-relative.'};$relative=$PacketPath.Replace('\','/').Trim();if($relative.Contains('..')-or $relative -notmatch '^ES/Output/.+\.json$'){throw 'PacketPath must remain under ES/Output.'};$full=Join-Path $root ($relative.Replace('/',[IO.Path]::DirectorySeparatorChar));if(-not(Test-Path -LiteralPath $full -PathType Leaf)){throw "Generation packet missing: $relative"};$raw=[Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes((Resolve-Path $full)));if($raw -match '(?i)"(?:approved|formalWrite)"\s*:\s*true'){throw 'Candidate generation cannot self-approve or perform formal writes.'};$p=$raw|ConvertFrom-Json;foreach($x in @('generationId','requestAuthority','candidateRoot','artifacts','approvalRequired')){if($null -eq $p.PSObject.Properties[$x]){throw "Generation field missing: $x"}};if([bool]$p.approvalRequired -ne $true){throw 'approvalRequired must be true.'};if(@($p.artifacts).Count -eq 0){throw 'At least one candidate artifact is required.'};foreach($a in @($p.artifacts)){foreach($x in @('candidateRelativePath','kind','formalTarget','validation')){if([string]::IsNullOrWhiteSpace([string]$a.$x)){throw "Artifact missing $x."}};$path=[string]$a.candidateRelativePath;if($path -notmatch '^candidate/'-or $path.Contains('..')-or [IO.Path]::IsPathRooted($path)){throw "Artifact escapes candidate root: $path"};if([string]$a.formalTarget -notmatch '^(Assets/Plugins/ES/AICommands/|\.agents/skills/es-)'){throw 'Formal target is outside the declared allowlist.'}};Write-Output "PASS: candidate generation is isolated, path-bounded, validation-gated and approval-required: $relative"
